function horas(min) {
  const h = Math.floor(min / 60), m = Math.round(min % 60);
  return h + "h" + (m ? (m < 10 ? "0" : "") + m : "");
}

async function run() {
  const hoje = dates.today();
  const recuo = (dates.weekday(hoje) + 6) % 7;
  const segunda = dates.startOfDay(hoje, -recuo);
  const eventos = (await calendar.events({from: segunda, to: dates.startOfDay(hoje, 1)}))
    .filter(e => e.start && e.end && e.start.indexOf("T") !== -1)
    .filter(e => !params.so_com_participantes || (e.attendees || []).length > 0)
    .map(e => ({title: e.title, start: e.start, ini: Date.parse(e.start), fim: Date.parse(e.end)}))
    .filter(e => e.fim > e.ini);
  if (!eventos.length) return;

  eventos.sort((a, b) => a.ini - b.ini);
  let total = 0, ini = eventos[0].ini, fim = eventos[0].fim;
  for (const e of eventos.slice(1)) {
    if (e.ini <= fim) { fim = Math.max(fim, e.fim); continue; }
    total += fim - ini; ini = e.ini; fim = e.fim;
  }
  total += fim - ini;
  const minutos = total / 60000;

  const maiores = eventos.slice().sort((a, b) => (b.fim - b.ini) - (a.fim - a.ini)).slice(0, 3);
  let text = "🗓️ Nesta semana: " + horas(minutos) + " em reuniões (" + eventos.length + (eventos.length === 1 ? " reunião" : " reuniões") + ").\n";
  text += minutos > params.limite * 60
    ? "Passou " + horas(minutos - params.limite * 60) + " do seu limite de " + horas(params.limite * 60) + "."
    : "Dentro do seu limite de " + horas(params.limite * 60) + ".";
  text += "\nAs mais longas:\n" + maiores.map(e => "• " + e.title + " — " + horas((e.fim - e.ini) / 60000) + " (" + dates.format(e.start, "EEE") + ")").join("\n");
  await notify.send({text});
}
